UPDATE ai_model_config
SET name = #{name}, model_name = #{modelName}, endpoint = #{endpoint}, api_key = #{apiKey},
    max_tokens = #{maxTokens}, temperature = #{temperature}, status = #{status}
WHERE id = #{id}

UPDATE prompt_template
SET name = #{name}, type = #{type}, content = #{content}, version = #{version}, status = #{status},
    variables = #{variables}, sort = #{sort}
WHERE id = #{id}
